<?php
declare(strict_types=1);
require __DIR__.'/lib.php';need_admin();
$cfg=require __DIR__.'/ahli-waris/config.php';
try {$db=new PDO('mysql:host='.$cfg['host'].';port='.($cfg['port']??3306).';dbname='.$cfg['database'].';charset=utf8mb4',$cfg['username'],$cfg['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_EMULATE_PREPARES=>false,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);}
catch(Throwable $e){error_log('Admin Arsip Waris: '.$e->getMessage());http_response_code(503);exit('Layanan arsip sedang tidak tersedia. Silakan menghubungi pengelola.');}
$db->exec('CREATE TABLE IF NOT EXISTS aw_archives (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, archive_year SMALLINT UNSIGNED NOT NULL, reference_no VARCHAR(100) NOT NULL, applicant_name VARCHAR(200) NOT NULL, deceased_name VARCHAR(200) NOT NULL, notes TEXT, attachment VARCHAR(120) NULL, created_by VARCHAR(100) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_year(archive_year)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4');
$db->exec('CREATE TABLE IF NOT EXISTS aw_archive_details (archive_id BIGINT UNSIGNED PRIMARY KEY, details_json LONGTEXT NULL, files_json LONGTEXT NULL, updated_by VARCHAR(80) NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4');
function aw_archive_row(PDO $db,int $id):?array {
 $st=$db->prepare('SELECT a.*,d.details_json,d.files_json FROM aw_archives a LEFT JOIN aw_archive_details d ON a.id=d.archive_id WHERE a.id=?');$st->execute([$id]);$row=$st->fetch();return $row?:null;
}
function aw_archive_photo(PDO $db,int $id,string $code):void {
 $row=aw_archive_row($db,$id);$files=$row?json_decode($row['files_json']?:'{}',true):[];
 $name=(string)($files[$code]??'');if(!$name||basename($name)!==$name){http_response_code(404);exit('Lampiran tidak ditemukan.');}
 $file=__DIR__.'/mobile-api/private/'.$name;
 if(!is_file($file)){http_response_code(404);exit('Lampiran tidak ditemukan.');}
 $mime=(new finfo(FILEINFO_MIME_TYPE))->file($file);if(!in_array($mime,['image/jpeg','image/png','image/webp'],true)){http_response_code(404);exit('Lampiran tidak ditemukan.');}
 header('Content-Type: '.$mime);header('Cache-Control: private, no-store');header('X-Content-Type-Options: nosniff');readfile($file);exit;
}
if(isset($_GET['photo'])&&isset($_GET['id']))aw_archive_photo($db,(int)$_GET['id'],(string)$_GET['photo']);
$labels=['r1'=>'Surat Pengantar RT/RW','r2'=>'Surat Permohonan','r3'=>'Surat Pernyataan Keabsahan','r4'=>'KTP, KK, dan Akta Lahir Ahli Waris','r5'=>'Surat Kematian','r6'=>'Surat Nikah','r7'=>'Akta Cerai (jika ada)','r8'=>'Surat Kematian Ahli Waris (jika ada)'];
$id=(int)($_GET['id']??$_POST['id']??0);$row=$id?aw_archive_row($db,$id):null;$detail=json_decode($row['details_json']??'{}',true)?:[];$files=json_decode($row['files_json']??'{}',true)?:[];
$notice='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 csrf_check();$year=(int)($_POST['archive_year']??0);$ref=trim((string)($_POST['reference_no']??''));$name=trim((string)($_POST['name']??''));$dead=trim((string)($_POST['deceased_name']??''));$nik=trim((string)($_POST['nik']??''));$notes=trim((string)($_POST['notes']??''));
 if($year<1900||$year>(int)date('Y')||$ref===''||$name===''||$dead==='')$error='Tahun, nomor surat, pemohon, dan pewaris wajib dilengkapi.';
 elseif($nik!==''&&!preg_match('/^\d{16}$/',$nik))$error='NIK harus terdiri dari 16 angka.';
 else {
  $details=[];foreach(['nik','phone','address','relation','birthplace','birthdate','marriage_date','deathdate','marital_status','heirs'] as $key)$details[$key]=trim((string)($_POST[$key]??''));
  $children=[];foreach(array_slice((array)($_POST['child_name']??[]),0,10) as $i=>$child){$child=trim((string)$child);if($child!=='')$children[]=['number'=>$i+1,'name'=>$child];}$details['children']=$children;
  $newFiles=[];$oldFiles=$files;
  try {
   $keys=array_merge(array_keys($labels),array_map(fn($i)=>'child_'.$i,range(1,10)));
   foreach($keys as $key){$f=$_FILES[$key]??null;if(!$f||($f['error']??4)===UPLOAD_ERR_NO_FILE)continue;
    if(($f['error']??4)!==UPLOAD_ERR_OK||($f['size']??0)>4*1024*1024||!is_uploaded_file($f['tmp_name']))throw new RuntimeException('Foto belum memenuhi persyaratan ukuran maksimum 4 MB.');
    $mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$mime]??null;if(!$ext)throw new RuntimeException('Lampiran harus berbentuk foto JPG, PNG, atau WebP.');
    $new=bin2hex(random_bytes(20)).'.'.$ext;$dest=__DIR__.'/mobile-api/private/'.$new;
    if(!move_uploaded_file($f['tmp_name'],$dest))throw new RuntimeException('Foto belum berhasil disimpan.');
    $newFiles[]=$dest;$files[$key]=$new;
   }
   $db->beginTransaction();
   if($id>0){$check=$db->prepare('SELECT id FROM aw_archives WHERE id=? FOR UPDATE');$check->execute([$id]);if(!$check->fetch())throw new RuntimeException('Arsip yang diminta tidak ditemukan.');$db->prepare('UPDATE aw_archives SET archive_year=?,reference_no=?,applicant_name=?,deceased_name=?,notes=? WHERE id=?')->execute([$year,substr($ref,0,100),substr($name,0,200),substr($dead,0,200),substr($notes,0,5000),$id]);}
   else{$st=$db->prepare('INSERT INTO aw_archives(archive_year,reference_no,applicant_name,deceased_name,notes,created_by) VALUES(?,?,?,?,?,?)');$st->execute([$year,substr($ref,0,100),substr($name,0,200),substr($dead,0,200),substr($notes,0,5000),'admin_web']);$id=(int)$db->lastInsertId();}
   $db->prepare('INSERT INTO aw_archive_details(archive_id,details_json,files_json,updated_by) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE details_json=VALUES(details_json),files_json=VALUES(files_json),updated_by=VALUES(updated_by)')->execute([$id,json_encode($details,JSON_UNESCAPED_UNICODE),json_encode($files,JSON_UNESCAPED_UNICODE),'admin_web']);
   $db->commit();header('Location: kelola-arsip-waris-v211.php?id='.$id.'&saved=1',true,303);exit;
  } catch(Throwable $e){if($db->inTransaction())$db->rollBack();foreach($newFiles as $path)@unlink($path);error_log('Admin Arsip Waris save: '.$e->getMessage());$error='Arsip belum dapat disimpan. Mohon periksa kembali data dan persyaratan.';$files=$oldFiles;}
 }
}
if(isset($_GET['saved']))$notice='Arsip Ahli Waris berhasil disimpan.';
if($id>0&&$row){$detail=json_decode($row['details_json']??'{}',true)?:[];$files=json_decode($row['files_json']??'{}',true)?:[];}
$rows=$db->query('SELECT id,archive_year,reference_no,applicant_name,deceased_name FROM aw_archives ORDER BY archive_year DESC,id DESC LIMIT 80')->fetchAll();
function ar_value(string $name,array $row,array $details):string {return esc($_POST[$name]??($row[$name]??$details[$name]??''));}
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Arsip Ahli Waris Cikoko</title><style>
*{box-sizing:border-box}body{margin:0;background:#f2f7fc;color:#17395a;font:13px system-ui,sans-serif}header{background:#11385d;color:#fff;padding:18px 22px;display:flex;justify-content:space-between}header a{color:#fff}main{max-width:1240px;padding:18px;margin:auto}.layout{display:grid;grid-template-columns:245px minmax(0,1fr);gap:16px}.panel{background:#fff;border:1px solid #dce5ef;border-radius:14px;padding:16px;margin-bottom:14px}h1{font-size:22px}h2{font-size:16px;margin:8px 0 18px;color:#174373}label{font-size:11px;font-weight:700;display:block;margin-bottom:5px}.two{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px 15px}.field{margin-bottom:12px}input,textarea,select{border:1px solid #cbdbe9;border-radius:8px;padding:10px;width:100%;font:inherit;background:#fff}button,.button{background:#256dd7;border:0;color:white;padding:10px 14px;border-radius:9px;cursor:pointer;text-decoration:none;display:inline-block}.outline{background:#ecf3fd;color:#1b5ba2}.archive-link{display:block;padding:10px;border-bottom:1px solid #e7eef7;color:#164775;text-decoration:none}.archive-link:hover{background:#f1f6ff}.photos{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:12px}.photo-card{padding:12px;border:1px solid #e0e9f2;border-radius:11px}.photo-card img{width:100%;height:130px;object-fit:contain;background:#f1f5f9;border-radius:7px}.photo-card input{font-size:11px}.notice{padding:12px;background:#e0f3e9;border-radius:9px}.error{padding:12px;background:#ffe6e6;border-radius:9px}@media(max-width:750px){.layout{grid-template-columns:1fr}.two{grid-template-columns:1fr}}
</style></head><body><header><b>Kelurahan Cikoko · Arsip Ahli Waris</b><a href="admin.php?type=waris">Kembali ke Admin</a></header><main><h1>Tambah / Edit Arsip Ahli Waris</h1><p>Input arsip tahun-tahun sebelumnya menggunakan format persyaratan yang sama dengan pengajuan warga.</p><?php if($notice):?><p class="notice"><?=esc($notice)?></p><?php endif;?><?php if($error):?><p class="error"><?=esc($error)?></p><?php endif;?><div class="layout"><aside class="panel"><a class="button" href="kelola-arsip-waris-v211.php">+ Tambah Arsip</a><h2>Daftar Arsip</h2><?php foreach($rows as $r):?><a class="archive-link" href="?id=<?=intval($r['id'])?>"><b><?=esc($r['reference_no'])?></b> · <?=esc($r['archive_year'])?><br><small><?=esc($r['applicant_name'])?></small></a><?php endforeach;?></aside><div><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=esc(csrf())?>"><input type="hidden" name="id" value="<?=intval($id)?>"><section class="panel"><h2>Data Surat dan Pemohon</h2><div class="two"><?php foreach(['archive_year'=>'Tahun Surat','reference_no'=>'Nomor Surat','name'=>'Nama Pemohon','nik'=>'NIK (16 angka)','phone'=>'No. HP','relation'=>'Hubungan dengan Pewaris'] as $key=>$label):?><div class="field"><label><?=esc($label)?></label><input name="<?=esc($key)?>" value="<?=$key==='archive_year'?esc($_POST[$key]??($row['archive_year']??date('Y'))):($key==='reference_no'?ar_value('reference_no',$row??[],$detail):($key==='name'?esc($_POST['name']??($row['applicant_name']??'')):ar_value($key,$row??[],$detail)))?>" <?=$key==='archive_year'?'type="number" min="1900" max="'.date('Y'). '"':''?> <?=in_array($key,['archive_year','reference_no','name'],true)?'required':''?>></div><?php endforeach;?></div><div class="field"><label>Alamat Lengkap</label><textarea name="address" rows="2"><?=ar_value('address',$row??[],$detail)?></textarea></div></section><section class="panel"><h2>Data Almarhum/Almarhumah</h2><div class="two"><?php foreach(['deceased_name'=>'Nama Pewaris','birthplace'=>'Tempat Lahir','birthdate'=>'Tanggal Lahir (YYYY-MM-DD)','marriage_date'=>'Tanggal Menikah (YYYY-MM-DD)','marital_status'=>'Status Perkawinan','deathdate'=>'Tanggal Meninggal (YYYY-MM-DD)'] as $key=>$label):?><div class="field"><label><?=esc($label)?></label><input name="<?=esc($key)?>" value="<?=$key==='deceased_name'?esc($_POST[$key]??($row['deceased_name']??'')):ar_value($key,$row??[],$detail)?>" <?=$key==='deceased_name'?'required':''?>></div><?php endforeach;?></div><div class="field"><label>Daftar Ahli Waris</label><textarea name="heirs" rows="4"><?=ar_value('heirs',$row??[],$detail)?></textarea></div><div class="field"><label>Catatan Arsip</label><textarea name="notes" rows="3"><?=ar_value('notes',$row??[],$detail)?></textarea></div></section><section class="panel"><h2>Persyaratan Dokumen</h2><div class="photos"><?php foreach($labels as $key=>$label):?><div class="photo-card"><b><?=esc($label)?></b><?php if(!empty($files[$key])):?><a target="_blank" href="?id=<?=intval($id)?>&photo=<?=urlencode($key)?>"><img loading="lazy" src="?id=<?=intval($id)?>&photo=<?=urlencode($key)?>" alt="<?=esc($label)?>"></a><?php endif;?><label>Ambil / Ganti Foto</label><input type="file" name="<?=esc($key)?>" accept="image/jpeg,image/png,image/webp"></div><?php endforeach;?></div></section><section class="panel"><h2>Daftar Anak (maksimal 10)</h2><div class="two"><?php for($i=1;$i<=10;$i++):$child=$detail['children'][$i-1]['name']??'';$key='child_'.$i;?><div class="photo-card"><label>Nama anak ke-<?=$i?></label><input name="child_name[]" value="<?=esc($_POST['child_name'][$i-1]??$child)?>"><label>Dokumen KTP, KK, dan Akta Lahir</label><?php if(!empty($files[$key])):?><a href="?id=<?=intval($id)?>&photo=<?=urlencode($key)?>" target="_blank"><img loading="lazy" src="?id=<?=intval($id)?>&photo=<?=urlencode($key)?>" alt="Dokumen anak ke-<?=$i?>"></a><?php endif;?><input type="file" name="<?=esc($key)?>" accept="image/jpeg,image/png,image/webp"></div><?php endfor;?></div></section><div class="panel"><button type="submit">Simpan Data Arsip</button> <button type="button" class="outline" onclick="window.print()">Cetak Ringkasan</button></div></form></div></div></main></body></html>
